function renderPick(){
  const L = PL.src || []; $("plPickBox").hidden = !L.length;
  $("plPick").innerHTML = L.map((t,i) => `<tr${t.on ? "" : ' style="opacity:.5"'}><td><input type="checkbox" data-pk="${i}" ${t.on ? "checked" : ""} style="width:auto" aria-label="出貨"></td>
    <td><span class="mono">${esc(t.itemCode||"")}</span><span class="sub">${esc(t.itemName || (itemById(t.itemId)||{}).name || "")}</span></td>
    <td class="r">${esc(String(t.qty0))}</td>
    <td class="r"><input data-pq="${i}" type="number" min="0" step="any" value="${esc(String(t.qty))}" style="width:100px;text-align:right" ${t.on ? "" : "disabled"}>${Number(t.qty) > t.qty0 ? '<span class="sub" style="color:var(--bad)">超過銷貨數量</span>' : ""}</td>
    <td><input data-pp="${i}" value="${esc(t.packLines||"")}" placeholder="例：10×36 + 1×20" style="min-width:160px" ${t.on ? "" : "disabled"}></td></tr>`).join("");
  const on = L.filter(t => t.on && Number(t.qty) > 0);
  $("plPickAll").checked = L.length && on.length === L.length;
  $("plPickSum").textContent = `已勾選 ${on.length} / ${L.length} 項，共 ${round(on.reduce((s,t)=>s+(Number(t.qty)||0),0))} PCS`;
}
$("plPick").addEventListener("change", e => {
  const el = e.target, L = PL.src || [];
  if (el.dataset.pk != null){ L[el.dataset.pk].on = el.checked; renderPick(); }
  else if (el.dataset.pq != null){ const t = L[el.dataset.pq]; t.qty = Number(el.value) || 0; t.packLines = pickPack(t, t.qty); renderPick(); }
  else if (el.dataset.pp != null){ L[el.dataset.pp].packLines = el.value.trim(); }
});
$("plPickAll").addEventListener("change", () => { (PL.src||[]).forEach(t => t.on = $("plPickAll").checked); renderPick(); });
$("plPickGo").addEventListener("click", () => {
  const sel = (PL.src||[]).filter(t => t.on && Number(t.qty) > 0).map(t => Object.assign({}, t, { qty:Number(t.qty) }));
  if (!sel.length) return msg("plMsg", "請至少勾選一個品項，出貨數量要大於 0。", "err");
  msg("plMsg", ""); PL.lines = buildLines(sel); $("plMarks").value = plMarks(PL.lines, $("plTo").value); renderPl();
  $("plStatus").textContent = `依勾選的 ${sel.length} 個品項產生，尚未儲存`;
});
function renderPick(){
  const L = PL.src || []; $("plPickBox").hidden = !L.length; const lots = PL.mode === "lots";
  $("plPickQ0").textContent = lots ? "可出數量" : "銷貨數量"; $("plAllWrap").hidden = !lots;
  $("plPickHint").textContent = lots
    ? "這張單還沒有出庫紀錄，下面列出這些品號已入庫、還沒出庫的貨（每筆入庫一列，含入庫時登記的尺寸和棧板重）。已依先進先出幫你勾到銷貨數量，可以改勾選、數量、包裝、尺寸和棧板重，再按「依勾選產生」。毛重 = 數量×單位毛重 + 棧板重。"
    : "勾選這次要出的品項，可以改出貨數量、包裝、尺寸和棧板重，再按「依勾選產生」，下方的 Packing List 會重新排。毛重 = 數量×單位毛重 + 棧板重。";
  const row = (t,i) => `<tr${t.on ? "" : ' style="opacity:.55"'}><td><input type="checkbox" data-pk="${i}" ${t.on ? "checked" : ""} style="width:auto" aria-label="出貨"></td>
    <td>${lots ? `<span class="sub">${t.noLot ? "庫存（找不到入庫紀錄）" : "入庫 " + esc(t.date||"")}${t.ref ? "｜" + esc(t.ref) : ""}${t.woNo ? "｜工單 " + esc(t.woNo) : ""}｜${esc(t.whId||"")}${t.partial ? `｜原入庫 ${esc(String(t.qtyIn))}，已出一部分` : ""}</span>` : `<span class="mono">${esc(t.itemCode||"")}</span><span class="sub">${esc(t.itemName || (itemById(t.itemId)||{}).name || "")}</span>`}</td>
    <td class="r">${esc(String(t.qty0))}</td>
    <td class="r"><input data-pq="${i}" type="number" min="0" step="any" value="${esc(String(t.qty))}" style="width:96px;text-align:right" ${t.on ? "" : "disabled"}>${Number(t.qty) > t.qty0 ? `<span class="sub" style="color:var(--bad)">超過${lots ? "可出" : "銷貨"}數量</span>` : ""}</td>
    <td><input data-pp="${i}" value="${esc(t.packLines||"")}" placeholder="例：10×36 + 1×20" style="min-width:150px" ${t.on ? "" : "disabled"}></td>
    <td><input data-pd="${i}" value="${esc(t.pack||"")}" placeholder="例：110×110×95" style="width:120px" ${t.on ? "" : "disabled"}></td>
    <td class="r"><input data-pw="${i}" type="number" min="0" step="any" value="${esc(t.palletWt ? String(t.palletWt) : "")}" style="width:80px;text-align:right" ${t.on ? "" : "disabled"}></td></tr>`;
  let html = "";
  if (lots){
    const codes = [...new Set(L.map(t => t.itemCode))];
    codes.forEach(c => {
      const g = L.map((t,i) => [t,i]).filter(x => x[0].itemCode === c), need = PL.need[c];
      const sel = round(g.filter(x => x[0].on).reduce((s,x) => s + (Number(x[0].qty)||0), 0)), have = round(g.reduce((s,x) => s + x[0].qty0, 0));
      const nm = g[0][0].itemName || (itemById(c)||{}).name || "";
      const st = need == null ? `<span class="muted">不在這張銷貨單上</span>` : sel === need ? `<span style="color:var(--ok)">已勾 ${sel} / 銷貨 ${need}</span>` : `<span style="color:var(--bad)">已勾 ${sel} / 銷貨 ${need}</span>`;
      html += `<tr><td colspan="7" style="background:var(--surface-2,rgba(0,0,0,.035))"><span class="mono"><b>${esc(c)}</b></span> ${esc(nm)}　${st}　<span class="muted">庫存 ${have}${need != null && have < need ? `，<b style="color:var(--bad)">不足 ${round(need - have)}</b>` : ""}</span></td></tr>`;
      html += g.map(x => row(x[0], x[1])).join("");
    });
    Object.keys(PL.need).filter(c => !codes.includes(c)).forEach(c => {
      html += `<tr><td colspan="7"><span class="mono"><b>${esc(c)}</b></span> <span style="color:var(--bad)">銷貨 ${PL.need[c]}，目前沒有庫存</span></td></tr>`; });
  } else html = L.map(row).join("");
  $("plPick").innerHTML = html;
  const on = L.filter(t => t.on && Number(t.qty) > 0);
  $("plPickAll").checked = L.length && on.length === L.length;
  $("plPickSum").textContent = `已勾選 ${on.length} / ${L.length} 筆，共 ${round(on.reduce((s,t)=>s+(Number(t.qty)||0),0))} PCS`;
}
/** 先進先出：每個品號從最早入庫的開始勾，勾到銷貨數量為止（最後一筆只出一部分時自動改數量和包裝） */
function pickFifo(){
  const rest = Object.assign({}, PL.need);
  (PL.src||[]).forEach(t => { const r = rest[t.itemCode]; t.qty = t.qty0; t.packLines = t.pk0;
    if (!(r > 0)) { t.on = false; return; }
    t.on = true; if (r < t.qty0) { t.qty = r; t.packLines = pickPack(t, r); } rest[t.itemCode] = round(r - t.qty); });
}
function lotRow(l){ const t = Object.assign({}, l, { type:"out", itemId:l.itemCode, qty0:Number(l.qty)||0, qty:Number(l.qty)||0, on:false });
  t.packLines = l.packLines || packText(packOf(l)); if (l.partial && t.packLines) t.packLines = pickPack(t, t.qty); t.pk0 = t.packLines; return t; }
$("plPick").addEventListener("change", e => {
  const el = e.target, L = PL.src || [];
  if (el.dataset.pk != null){ L[el.dataset.pk].on = el.checked; renderPick(); }
  else if (el.dataset.pq != null){ const t = L[el.dataset.pq]; t.qty = Number(el.value) || 0; t.packLines = pickPack(t, t.qty); renderPick(); }
  else if (el.dataset.pp != null){ L[el.dataset.pp].packLines = el.value.trim(); }
  else if (el.dataset.pd != null){ L[el.dataset.pd].pack = el.value.trim(); }
  else if (el.dataset.pw != null){ L[el.dataset.pw].palletWt = Number(el.value) || 0; }
});
$("plPickAll").addEventListener("change", () => { (PL.src||[]).forEach(t => t.on = $("plPickAll").checked); renderPick(); });
$("plAllLots").addEventListener("change", async () => {
  try{
    if ($("plAllLots").checked){
      const r = await busy(() => call("getPacking", { sc:PL.sc, allLots:true }));
      const have = new Set((PL.src||[]).map(t => t.itemCode));
      (r.lots||[]).filter(l => !have.has(l.itemCode)).forEach(l => PL.src.push(Object.assign(lotRow(l), { extra:true })));
    } else PL.src = (PL.src||[]).filter(t => !t.extra);
    renderPick();
  }catch(err){ msg("plMsg", err.message, "err"); }
});
$("plPickGo").addEventListener("click", () => {
  const sel = (PL.src||[]).filter(t => t.on && Number(t.qty) > 0).map((t,i) => Object.assign({}, t, { qty:Number(t.qty), ts:i }));
  if (!sel.length) return msg("plMsg", "請至少勾選一筆，出貨數量要大於 0。", "err");
  msg("plMsg", ""); PL.lines = buildLines(sel); $("plMarks").value = plMarks(PL.lines, $("plTo").value); renderPl();
  $("plStatus").textContent = `依勾選的 ${sel.length} 筆產生，尚未儲存`;
});

$("plAllLots").checked = false; PL.need = {};
if (r.lots){
  PL.mode = "lots"; r.txns.filter(t=>t.type==="out").forEach(t => PL.need[t.itemCode] = round((PL.need[t.itemCode]||0) + (Number(t.qty)||0)));
  PL.src = r.lots.map(lotRow); pickFifo();
} else {
  PL.mode = "txns";
  PL.src = r.txns.filter(t=>t.type==="out").map(t => Object.assign({}, t, { qty0:Number(t.qty)||0, qty:Number(t.qty)||0, on:true, packLines: t.packLines || packText(packOf(t)) }));
}
renderPick();

PL.src = r.lots.map(lotRow);
r.txns.filter(t => t.type==="out" && !PL.src.some(x => x.itemCode === t.itemCode)).forEach(t => PL.src.push(Object.assign(lotRow(Object.assign({}, t, { qty:0 })), { fromSlip:true, qty0:Number(t.qty)||0, qty:Number(t.qty)||0, pk0:t.packLines||"", packLines:t.packLines||"", whId:"" })));
pickFifo();
